import { getBallotVerificationDetails } from '~/client';

export const useBallotDetails = defineQuery(() => {
  const route = useRoute('verification-ballots-id');

  const ballotId = computed(() => route.params.id);

  const { data, error, isLoading } = useQuery({
    key: () => ['ballot.details', ballotId.value],
    query: () => getBallotVerificationDetails({ composable: '$fetch', path: { ballot_id: ballotId.value } }),
    enabled: () => route.name === 'verification-ballots-id',
  });

  return {
    data,
    info: computed(() => data.value?.ballot || null),
    pages: computed(() => data.value?.ballot_pages || []),
    validSignatures: computed(() => data.value?.valid_signatures || []),
    error,
    isLoading,
  };
});
